def even_odd_palindrome(n):
    # Initialize a counter for even and odd palindromes
    even_count, odd_count = 0, 0

    # Iterate from 1 to n
    for i in range(1, n + 1):
        # Check if the current number is a palindrome
        if str(i) == str(i)[::-1]:
            # Increment the counter for even or odd palindromes
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    # Return a tuple with the count of even and odd palindromes
    return even_count, odd_count
